/**
 * Host half of dsh-media-player. Registers the model-facing `media_add` tool:
 * the model passes a playable video/audio URL, the tool validates it and appends
 * a durable `plugin/media-add` session event. The plugin's browser half then
 * folds that event into a chat node rendered as a player, so the media appears
 * inline in the conversation (and survives reload/replay via the session log).
 * @module dsh-media-player
 */

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from '@deepseek-ai/dsh-tools'
import type { GenericCallView } from '@deepseek-ai/dsh-tools'
import { mediaPayload } from './core.ts'
import { MEDIA_MIME_TYPES } from './media-types.ts'

export const name = 'media-player'
export const inject = ['tools']

/** Model-facing arguments of `media_add`. */
export interface MediaAddArgs {
  url: string
  mimeType: string
  title?: string
}

const DESCRIPTION =
  'Surface a playable video or audio asset into the conversation as a media node. '
  + 'Pass an absolute http(s) `url` to the media file and its `mimeType` '
  + '(video/mp4, video/webm, audio/mpeg, audio/wav, audio/ogg, audio/mp4); the chat then renders it '
  + 'as an inline video or audio player. Use when a task produces or references a media file the '
  + 'user should play directly in the chat. The URL and MIME type are validated before the asset is added.'

/** The pending-call card. */
export function mediaCallView(args: MediaAddArgs): GenericCallView {
  return { card: 'generic', title: 'Add media', kind: 'other', rawInput: args }
}

export function apply(ctx: Context): void {
  ctx.tools.register(defineTool({
    name: 'media_add',
    description: DESCRIPTION,
    parameters: {
      url: {
        type: 'string',
        required: true,
        description: 'Absolute http(s) URL of the playable media file.',
      },
      mimeType: {
        type: 'string',
        required: true,
        enum: [...MEDIA_MIME_TYPES],
        description: 'The media MIME type; video/* renders a video player, audio/* an audio player.',
      },
      title: {
        type: 'string',
        description: 'Optional short label shown above the player.',
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          url: { type: 'string', required: true },
          mimeType: { type: 'string', required: true, enum: [...MEDIA_MIME_TYPES] },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: `Added media (${value.mimeType}): ${value.url}`,
      }],
    },
    isConcurrencySafe: () => true,
    async execute(args, exec) {
      const payload = mediaPayload(args.url, args.mimeType, args.title)
      const session = exec.agent?.session
      if (session === undefined) {
        throw new Error('media_add requires an owning agent session')
      }
      session.append('plugin/media-add', payload)
      return { url: payload.url, mimeType: payload.mimeType }
    },
    presentCall: mediaCallView,
  }))
}

// Re-exported helpers for the package surface and tests.
export { isHttpUrl, isMediaMimeType, mediaPayload } from './core.ts'
export { MEDIA_MIME_TYPES } from './media-types.ts'
export type { MediaAddEventData, MediaMimeType } from './media-types.ts'
